/** A module function minus its leading context parameter. */
export type Op<F> = F extends (fc: FcCtx, ...a: infer A) => infer R ? (...a: A) => R : never;

/** Bind a module function to one context so it can be passed around as a value. */
export function bindOp<F extends (fc: FcCtx, ...a: never[]) => unknown>(fc: FcCtx, f: F): Op<F> {
  return ((...a: never[]) => f(fc, ...a)) as Op<F>;
}
